def solve(payload):
    import math
    a, b = [math.radians(value) for value in payload["angles_deg"]]
    ca, sa, cb, sb = math.cos(a), math.sin(a), math.cos(b), math.sin(b)
    determinant = ca * sb - sa * cb
    if abs(determinant) <= 1e-10:
        return {"error": "singular_directions"}
    fx, fy = payload["load_n"]
    f1 = (-fx * sb + cb * fy) / determinant
    f2 = (-ca * fy + fx * sa) / determinant
    return {"forces_n": [f1, f2]}

